-- BIRD database 'coinmarketcap' translated to PostgreSQL.
-- Generated by research/advtext2sql/delivery/build.py from the live
-- benchmark server; types, keys and column comments are the server's own.

CREATE TABLE "coins" (
    "id" bigint NOT NULL,
    "name" text,
    "slug" text,
    "symbol" text,
    "status" text,
    "category" text,
    "description" text,
    "subreddit" text,
    "notice" text,
    "tags" text,
    "tag_names" text,
    "website" text,
    "platform_id" bigint,
    "date_added" text,
    "date_launched" text,
    PRIMARY KEY ("id")
);

CREATE TABLE "historical" (
    "date" date,
    "coin_id" bigint,
    "cmc_rank" bigint,
    "market_cap" real,
    "price" real,
    "open" real,
    "high" real,
    "low" real,
    "close" real,
    "time_high" text,
    "time_low" text,
    "volume_24h" real,
    "percent_change_1h" real,
    "percent_change_24h" real,
    "percent_change_7d" real,
    "circulating_supply" real,
    "total_supply" real,
    "max_supply" real,
    "num_market_pairs" bigint
);

